<script setup lang="ts">
import TimeZoneSelect from '../writing/TimeZoneSelect.vue'
import AdvancedNotificationFields from './AdvancedNotificationFields.vue'
import {useRoute} from 'vue-router'
import {ref,onMounted,computed} from 'vue'
import {request} from '../api'
import {confirmAction} from '../ui/confirm'
import PrivatePreview from '../admin/PrivatePreview.vue'
const saving=ref(false),notificationBusy=ref(false)
const route=useRoute()
const futureReminders=ref<any>({items:[]})
const now=new Date(),month=ref(now.getFullYear()*12+now.getMonth()),items=ref<any[]>([]),today=ref(''),error=ref(''),admin=ref(false),events=ref<any[]>([]),draft=ref<any>(),editing=ref(''),detail=ref<any>(),notification=ref<any>(),logs=ref<any[]>([]),logPage=ref(1),notice=ref(''),records=ref<any[]>([]),recordSearch=ref('')
const label=computed(()=>Math.floor(month.value/12)+'年'+(month.value%12+1)+'月')
const iso=(d:Date)=>d.toISOString().slice(0,10)
const start=computed(()=>new Date(Date.UTC(Math.floor(month.value/12),month.value%12,1)))
const cells=computed(()=>{const d=start.value,first=new Date(d.getTime()-((d.getUTCDay()+6)%7)*86400000);return Array.from({length:42},(_,i)=>{const day=new Date(first.getTime()+i*86400000),date=iso(day);return {date,number:day.getUTCDate(),current:day.getUTCMonth()===d.getUTCMonth(),items:items.value.filter(e=>e.date===date)}})})
async function load(){try{const end=new Date(Date.UTC(Math.floor(month.value/12),month.value%12+1,0)),r=await request('/calendar?start='+iso(start.value)+'&end='+iso(end));items.value=r.items;today.value=r.today;error.value=''}catch{error.value='无法读取纪念日历'}}
async function adminLoad(){events.value=await request('/admin/calendar/events');notification.value=await request('/admin/calendar/notification');logs.value=await request('/admin/calendar/logs?page='+logPage.value)}
onMounted(async()=>{await load();if(typeof route.query.event==='string')await show(route.query.event);try{admin.value=(await request('/admin/status')).is_admin;if(admin.value)await adminLoad()}catch{}})
async function change(d:number){month.value+=d;await load()}
async function show(id:string,page=1){try{detail.value=await request('/calendar/'+id+(page===1?'':'?memory_page='+page))}catch{error.value='无法读取回忆'}}
function edit(e?:any){futureReminders.value={items:[]};if(e?.id)void request('/admin/calendar/events/'+e.id+'/schedule').then(r=>futureReminders.value=r).catch(()=>error.value='读取未来提醒失败');editing.value=e?.id||'';draft.value=e?JSON.parse(JSON.stringify(e)):{name:'',kind:'anniversary',rule:{calendar:'solar',year:now.getFullYear(),month:now.getMonth()+1,day:now.getDate(),leap_month:false,repeat:'yearly',interval:1,missing:'skip',lunar_leap:'skip'},reminders:{enabled:true,on_day:true,offsets:[7,3,1],time:null},memories:[],expected_revision:0};if(draft.value.id)delete draft.value.id}
function offsets(value:string){const raw=value.split(/[,，\s]+/).filter(Boolean);draft.value.reminders.offsets=raw.map(Number)}
async function searchRecords(){try{records.value=(await request('/admin/content/records?page_size=100&q='+encodeURIComponent(recordSearch.value))).items}catch{error.value='读取文章失败'}}
async function save(){if(saving.value)return;saving.value=true;try{const r=await request('/admin/calendar/events'+(editing.value?'/'+editing.value:''),{method:editing.value?'PUT':'POST',body:JSON.stringify(draft.value)});draft.value=undefined;await adminLoad();await load();await show(r.id)}catch{error.value='保存失败，请核对日期、提醒和版本冲突；当前输入保留'}finally{saving.value=false}}
async function remove(e:any){if(!await confirmAction('删除此纪念日？会停止未发送提醒，保留发送日志和文章。'))return;try{await request('/admin/calendar/events/'+e.id+'?expected_revision='+e.expected_revision,{method:'DELETE'});await adminLoad();await load();detail.value=undefined}catch{error.value='删除失败，请重新读取版本'}}
async function saveNotify(){if(notificationBusy.value)return;notificationBusy.value=true;try{await request('/admin/calendar/notification',{method:'PUT',body:JSON.stringify(notification.value)});notification.value=await request('/admin/calendar/notification');notice.value='通知设置已保存'}catch{notice.value='保存失败，请检查模板、安全限制、时区或版本；当前输入保留'}finally{notificationBusy.value=false}}
async function testNotify(){if(notificationBusy.value)return;notificationBusy.value=true;try{const r=await request('/admin/calendar/notification/test',{method:'POST'});notice.value=r.note||('请求状态：'+r.state)}catch{notice.value='测试请求未确认成功'}finally{notificationBusy.value=false}}
async function retry(id:string){if(!await confirmAction('请先核对外部发送结果。手动重试可能造成重复通知，是否继续？'))return;try{await request('/admin/calendar/logs/'+id+'/retry',{method:'POST',body:JSON.stringify({confirmation:'我已核对外部发送结果并接受重复通知风险'})});logs.value=await request('/admin/calendar/logs?page='+logPage.value)}catch{error.value='无法重试该节点'}}
</script>
<template><main class="anniversary-calendar"><RouterLink to="/">返回首页</RouterLink><h1>纪念日历</h1><div class="actions"><button @click="change(-1)">上个月</button><h2>{{label}}</h2><button @click="change(1)">下个月</button><button v-if="admin" @click="edit()">新增纪念日</button></div><p role="status">{{error}}</p><div class="calendar-grid" role="grid" :aria-label="label"><div v-for="d in ['一','二','三','四','五','六','日']" role="columnheader">{{d}}</div><div v-for="c in cells" :key="c.date" role="gridcell" :aria-label="c.date" :class="{muted:!c.current,today:c.date===today}"><span>{{c.number}}</span><button v-for="e in c.items" :key="e.id" class="quiet" @click="show(e.id)">{{e.name}}</button></div></div><section><h2>本月事件</h2><button v-for="e in items" :key="e.id+e.date" class="calendar-event quiet" @click="show(e.id)">{{e.date}} · {{e.name}} · {{e.date===today?'今天':e.days_left<0?'已过'+(-e.days_left)+'天':'还有'+e.days_left+'天'}} · {{e.years}}周年</button><p v-if="!items.length">本月暂无事件。</p></section><section v-if="detail" class="calendar-detail"><h2>{{detail.name}}</h2><h3>未来发生日期</h3><p>{{detail.upcoming.join('、')||'支持范围内无下一次日期'}}</p><p>{{detail.note}}</p><section v-for="[key,title] in [['dedicated_memories','专属回忆'],['day_memories','当天回忆']]" :key="key"><h3>{{title}}</h3><article v-for="r in detail[key]" :key="r.id"><PrivatePreview v-if="r.cover" :id="r.cover.id" :alt="r.cover.alt"/><RouterLink :to="'/posts/'+r.id">{{r.display_date}} · {{r.title}}</RouterLink></article><div v-if="key==='day_memories'&&detail.day_memory_total>24" class="actions"><button :disabled="detail.memory_page<=1" @click="show(detail.id,detail.memory_page-1)">上一页回忆</button><span>{{detail.memory_page}} · 共 {{detail.day_memory_total}} 篇</span><button :disabled="detail.memory_page*24>=detail.day_memory_total" @click="show(detail.id,detail.memory_page+1)">下一页回忆</button></div></section></section>
<section v-if="admin"><h2>日期管理</h2><article v-for="e in events" :key="e.id"><strong>{{e.name}}</strong><button @click="edit(e)">编辑</button><button class="quiet" @click="remove(e)">删除</button></article><form v-if="draft" class="calendar-form" @submit.prevent="save"><label>名称<input v-model="draft.name" required maxlength="200"/></label><label>类型<select aria-label="类型" v-model="draft.kind"><option value="birthday">生日</option><option value="anniversary">周年纪念</option><option value="important">重要日期</option><option value="once">一次性提醒</option></select></label><label>历法<select aria-label="历法" v-model="draft.rule.calendar"><option value="solar">公历</option><option value="lunar">农历（1900–2099）</option></select></label><div class="actions"><label>年份<input v-model.number="draft.rule.year" type="number" required min="1" max="9998"/></label><label>月<input v-model.number="draft.rule.month" type="number" required min="1" max="12"/></label><label>日<input v-model.number="draft.rule.day" type="number" required min="1" max="31"/></label></div><label v-if="draft.rule.calendar==='lunar'"><input v-model="draft.rule.leap_month" type="checkbox"/>农历闰月</label><label>重复<select aria-label="重复" v-model="draft.rule.repeat"><option value="once">单次</option><option value="yearly">每年</option><option v-if="draft.rule.calendar==='solar'" value="monthly">每月</option><option v-if="draft.rule.calendar==='solar'" value="weekly">每周</option><option v-if="draft.rule.calendar==='solar'" value="interval">每隔若干天</option></select></label><label>周期间隔<input v-model.number="draft.rule.interval" type="number" min="1" max="366"/></label><label>不存在的日期<select aria-label="不存在的日期" v-model="draft.rule.missing"><option value="skip">跳过该次</option><option value="last_day">该月最后有效日</option><option v-if="draft.rule.calendar==='solar'" value="march_1">2月29日改为3月1日</option></select></label><label v-if="draft.rule.calendar==='lunar'">无对应闰月时<select aria-label="无对应闰月时" v-model="draft.rule.lunar_leap"><option value="skip">跳过该年</option><option value="regular">使用同月非闰月</option></select></label><label><input v-model="draft.reminders.enabled" type="checkbox"/>启用此纪念日通知</label><label><input v-model="draft.reminders.on_day" type="checkbox"/>当天提醒（独立于提前提醒）</label><label>提前天数（逗号分隔）<input :value="draft.reminders.offsets.join(',')" @change="offsets(($event.target as HTMLInputElement).value)"/></label><label>提醒时间覆盖（留空使用全局）<input v-model="draft.reminders.time" type="time" @change="!draft.reminders.time&&(draft.reminders.time=null)"/></label><details><summary>设置专属回忆</summary><label>搜索文章<input v-model="recordSearch"/></label><button type="button" @click="searchRecords">搜索</button><label v-for="r in records" :key="r.id"><input type="checkbox" v-model="draft.memories" :value="r.id"/>{{r.title}}</label><p>已保留 {{draft.memories.length}} 篇专属回忆；不勾选不影响自动日期匹配。</p></details><section v-if="futureReminders.items.length"><h3>已保存配置的未来提醒 · {{futureReminders.timezone}}</h3><p v-for="r in futureReminders.items" :key="r.occurrence+String(r.offset)">{{r.planned_at}} · {{r.offset===0?'当天提醒':'提前'+r.offset+'天'}}</p></section><footer><button type="submit" :disabled="saving">保存纪念日</button><button type="button" class="quiet" @click="draft=undefined">取消</button></footer></form>
<details v-if="notification" class="notification-settings" open><summary>HTTP 通知设置及日志（仅管理员）</summary><form @submit.prevent="saveNotify"><fieldset :disabled="notificationBusy"><label><input v-model="notification.enabled" type="checkbox"/>启用自动通知</label><label>通知 URL 模板<input v-model="notification.url_template" class="notification-url" aria-label="通知 URL 模板" type="text" autocomplete="off" autocapitalize="off" :spellcheck="false" maxlength="4000"/></label><p>变量可用于路径或查询参数值：{title}、{content}、{name}、{date}、{days_left}、{years}、{calendar_type}，路径与查询参数分别安全编码。公开目标须使用 HTTPS；内网目标需服务器明确白名单。</p><AdvancedNotificationFields :value="notification" :disabled="notificationBusy"/><TimeZoneSelect v-model="notification.timezone" label="站点时区" :disabled="notificationBusy"/><label>默认通知时间<input v-model="notification.time" type="time" required/></label><footer><button :disabled="notificationBusy">保存通知设置</button><button type="button" class="quiet" :disabled="notificationBusy" @click="testNotify">测试已保存配置</button></footer></fieldset></form><p role="status">{{notice}}</p><p>HTTP 2xx 仅表示HTTP层请求成功；不确定状态不会自动重发，手动重试前须核对外部结果。</p><article v-for="r in logs" :key="r.id" class="reminder-log"><strong>{{r.name}} · {{r.occurrence}} · 提前{{r.offset}}天</strong><p>计划：{{r.planned_at}} / 尝试：{{r.attempted_at||'未尝试'}} / 接口成功：{{r.sent_at||'未确认'}} · {{r.state}} · HTTP {{r.http_status||'—'}} · {{r.error}}</p><button v-if="r.state==='failed'||r.state==='uncertain'" @click="retry(r.id)">核对后手动重试</button></article><button :disabled="logPage<=1" @click="logPage--;adminLoad()">上一页日志</button><button :disabled="logs.length<50" @click="logPage++;adminLoad()">下一页日志</button></details></section></main></template>
<style scoped>.anniversary-calendar{max-width:1050px;margin:auto;padding:24px;min-width:0}.calendar-grid{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:4px}.calendar-grid>[role=gridcell]{min-height:84px;padding:6px;border:1px solid var(--line);min-width:0;overflow-wrap:anywhere}.calendar-grid button{font-size:13px;display:block;width:100%;padding:4px;overflow-wrap:anywhere}.today{outline:2px solid var(--accent)}.calendar-event{display:block;text-align:left;width:100%}.calendar-detail img{max-width:160px}.calendar-form,.reminder-log{border:1px solid var(--line);padding:16px;margin-block:12px}.calendar-form label{display:block}.calendar-form input:not([type=checkbox]),.calendar-form select{max-width:100%;box-sizing:border-box}.calendar-form input[type=checkbox]{width:auto}footer{position:sticky;bottom:0;background:var(--paper);padding:12px 0 max(12px,env(safe-area-inset-bottom));display:flex;gap:8px;flex-wrap:wrap}.reminder-log{overflow-wrap:anywhere}@media(max-width:600px){.anniversary-calendar{padding:12px}.calendar-grid>[role=gridcell]{min-height:68px;padding:3px}.calendar-grid button{font-size:11px}}</style>

<style scoped>.notification-settings{border:1px solid var(--line);padding:16px;border-radius:var(--ui-radius);margin-block:24px;min-width:0}.notification-settings fieldset{min-width:0;border:0;padding:0;margin:0}.notification-settings label{display:block;margin-block:10px}.notification-settings input:not([type=checkbox]){width:100%;min-width:0;max-width:100%;box-sizing:border-box}.notification-settings .notification-url{font-family:ui-monospace,monospace}.notification-settings p{overflow-wrap:anywhere}</style>
